import type { Config } from './config.js';
import { client } from './repository.js';
import { ApiFailure } from './domain.js';
/** Public output is generated by a narrowly scoped SQL function, never raw tables. */
export async function monitoringSnapshot(cfg:Config){
 if(!cfg.serviceKey)throw new ApiFailure(503,'MONITORING_UNAVAILABLE','Мониторинг не настроен');
 const {data,error}=await client(cfg,undefined,cfg.serviceKey).rpc('demo_monitoring_snapshot');
 if(error||data?.schemaVersion!==1||data?.scope!=='synthetic-demo-only')throw new ApiFailure(503,'MONITORING_UNAVAILABLE','Мониторинг временно недоступен');
 return data;
}
